import{_ as o,a as i,b as a,c as n,d,e as l,f as u}from"./chunks/OOP_UI3.DGHtp2cm.js";import{_ as c,C as p,o as m,c as h,a3 as r,j as t,E as O,w as b}from"./chunks/framework.g9mfNVRQ.js";const U=JSON.parse('{"title":"Algorithme externe (OOP)","description":"","frontmatter":{"source_hash":"bb1a1f1faf","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/use/OOP.md","filePath":"fr/use/OOP.md"}'),g={name:"fr/use/OOP.md"};function v(f,e,_,P,L,z){const s=p("big");return m(),h("div",null,[e[1]||(e[1]=r('<p>Les algorithmes hors processus (Out of process algorithms) sont des applications externes chargées d&#39;effectuer des traitements de données que xDrip ne fournit pas directement.</p><p>Ils ne sont plus utilisés aujourd&#39;hui que pour les capteurs Libre et les transmetteurs.</p><p>Il existe deux familles différentes d&#39;algorithmes hors processus (OOP) :</p><h3 id="oop1" tabindex="-1">OOP1 <a class="header-anchor" href="#oop1" aria-label="Permalink to &quot;OOP1 {#oop1}&quot;">​</a></h3><img src="'+o+'" style="zoom:75%;"><div class="warning custom-block"><p class="custom-block-title">Anciennes versions d&#39;Android UNIQUEMENT</p><p>La version d&#39;Android maximale prise en charge est la 9.<br> Quelques téléphones sous Android 10 et plus ont été signalés comme fonctionnant avec OOP1new/OOP1us.</p></div><table tabindex="0"><thead><tr><th>Version OOP</th><th>Date de version</th><th>Capteurs pris en charge</th><th>Taille du fichier</th></tr></thead><tbody><tr><td>OOP1 (2bb9458)</td><td>2018-08-26</td><td>Libre</td><td>17.1MB</td></tr><tr><td>OOP1new (fa218ef)</td><td>2019-11-22</td><td>Libre, Libre 2 EU</td><td>25.3MB</td></tr><tr><td>OOP1us (e901151) - <strong>ne pas utiliser : utilisez OOP2</strong></td><td>2019-09-13</td><td>Libre 14 jours US (ancien)</td><td>27.8MB</td></tr></tbody></table><p>OOP1 fournit des valeurs similaires à celles du lecteur du fabricant, sans étalonnage. Vous avez besoin d&#39;un <a href="./../install/libreBT.html">transmetteur compatible</a> si vous en utilisez un. OOP1 s&#39;applique aussi aux résultats des scans NFC.</p><div class="warning custom-block"><p class="custom-block-title">Aucun étalonnage possible</p><p>Les étalonnages sont ignorés lorsque vous utilisez OOP1.<br> C&#39;est une mesure de sécurité, car xDrip ne peut pas vérifier la cohérence des données fournies par OOP1.</p></div><p>Deux versions sont disponibles : <a href="https://drive.google.com/open?id=13ERWcSVSFMLy9rhpbv5rArFrnDuAzriM" target="_blank" rel="noreferrer">Libre 1 et Libre 2 EU</a> ou <a href="https://drive.google.com/open?id=172whZZYTyE_ZEuN0T-zhdMKhucy6jP-a" target="_blank" rel="noreferrer">Libre 14 jours US</a>. <em>Remarque : vous devez être connecté à votre compte Google pour accéder aux liens ci-dessus</em></p><p>L&#39;algorithme hors processus doit être <a href="./misc.html#out-of-process-algorithm">activé</a> lorsque vous utilisez OOP1.</p><h3 id="oop2" tabindex="-1">OOP2 <a class="header-anchor" href="#oop2" aria-label="Permalink to &quot;OOP2 {#oop2}&quot;">​</a></h3><img src="'+i+'" style="zoom:75%;"><p>OOP2 assure le décodage des capteurs Libre 14 jours US et Libre 2 EU, soit en connexion directe (Libre 2 EU uniquement), soit avec un <a href="./../install/libreBT.html">transmetteur compatible</a>.</p><div class="info custom-block"><p class="custom-block-title">L&#39;étalonnage est facultatif</p><p>Vous pouvez soit étalonner à partir des données brutes, soit ne pas étalonner, soit ajouter un étalonnage aux données natives.<br> Consultez les <a href="./misc.html#oop2">paramètres OOP2</a>.</p></div><p><strong>N&#39;utilisez que la dernière application OOP2 avec la dernière version de xDrip.</strong></p>',16)),t("p",null,[t("strong",null,[t("u",null,[O(s,null,{default:b(()=>[...e[0]||(e[0]=[t("a",{href:"https://drive.google.com/file/d/1106h2s12b3Ev9gKCTU2G75q8h9ChHjcz/view?usp=sharing",target:"_blank",rel:"noreferrer"},"→ Téléchargez la dernière version d'OOP2 ici. ←",-1)])]),_:1})])])]),e[2]||(e[2]=r('<p><em>Remarque : vous devez être connecté à votre compte Google pour accéder au lien ci-dessus.</em></p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p><em>Algorithme Libre hors processus</em> (OOP1) doit être <a href="./misc.html#out-of-process-algorithm">désactivé dans xDrip</a> lorsque vous utilisez OOP2.</p></div><table tabindex="0"><thead><tr><th>Version OOP</th><th>Date de version</th><th>Capteurs pris en charge</th><th>Taille du fichier</th></tr></thead><tbody><tr><td>OOP2 (70129ac) - <strong>ne pas utiliser</strong></td><td>2021-12-04</td><td>Libre 2 EU</td><td>2.63MB</td></tr><tr><td>OOP2new (93e5cac) - <strong>ne pas utiliser</strong></td><td>2020-12-08</td><td>Libre 14 jours US, Libre 2 EU</td><td>2.65MB</td></tr><tr><td>OOP2 1.2 (8a0ee8f) - <strong>ne pas utiliser</strong></td><td>2022-06-10</td><td>Libre 14 jours US (ancien), Libre 2 EU</td><td>2.66MB</td></tr><tr><td>OOP2_e6 (6de6678) - <strong>ne pas utiliser</strong></td><td>2023-01-10</td><td>Libre 14 jours US (nouveau), Libre 2 EU</td><td>2.66MB</td></tr><tr><td>OOP2_more (27da3f5)</td><td>2023-05-25</td><td>Libre 14 jours US (nouveau), Libre 2 EU (nouveau)</td><td>2.66MB</td></tr><tr><td>OOP2_c6_09_31 (27da3f5)</td><td>2024-05-31</td><td>Libre 14 jours US, Libre 2/2+ EU</td><td>2.7MB</td></tr><tr><td>OOP2-7f0e31 (27da3f5)</td><td>2025-06-12</td><td>Libre 14 jours US, Libre 2/2+ EU</td><td>2.73MB</td></tr><tr><td><strong>OOP2-21_9_25 (05d1989)</strong></td><td><strong>2025-09-21</strong></td><td><strong>Libre 14 jours US, Libre 2/2+ EU</strong></td><td><strong>2.73MB</strong></td></tr></tbody></table><h3 id="auto-detection" tabindex="-1">Détection automatique <a class="header-anchor" href="#auto-detection" aria-label="Permalink to &quot;Détection automatique {#auto-detection}&quot;">​</a></h3><p>Certaines anciennes versions de xDrip détectent la présence ou la nécessité de l&#39;algorithme hors processus.</p><p>Activez-le <u>uniquement</u> pour OOP1.<br><strong>Ne l&#39;activez pas pour OOP2</strong>. Si vous l&#39;avez activé par erreur : <a href="./misc.html#out-of-process-algorithm">désactivez</a> OOP1.</p><img src="'+a+'" style="zoom:75%;"><h3 id="settings" tabindex="-1">Paramètres <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Paramètres {#settings}&quot;">​</a></h3><p>Use service correspond à l&#39;activation ou la désactivation de l&#39;application OOP. Si vous voulez l&#39;utiliser, cette option doit être activée.</p><img src="'+n+'" style="zoom:75%;"><p>Foreground service est un complément qui réduit le risque que l&#39;application soit mise en veille par le téléphone. Cela n&#39;empêchera pas Google Play Protect de l&#39;arrêter.<br> Activez-le si vous perdez des données (<strong>recommandé</strong>).</p><img src="'+d+'" style="zoom:75%;"><p>Direct intent peut être activé si votre montre Wear OS autonome le nécessite (transmetteur nécessaire).</p><img src="'+l+'" style="zoom:75%;"><p>Vous pouvez choisir la période à laquelle OOP vérifie qu&#39;il est disponible.<br> En cas de perte de données, vous pouvez réduire l&#39;intervalle. Plus l&#39;intervalle est court, plus la consommation de batterie est élevée.</p><img src="'+u+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 15/12/2024</em></a></p>',18))])}const E=c(g,[["render",v]]);export{U as __pageData,E as default};
